// ioBroker object: script.js.common.go-E_V3_Phasen
// name: go-E_V3_Phasen
// engineType: Blockly
// enabled: True

var datum, txt;

// Beschreibe diese Funktion …
async function Logfile(datum, txt) {
    if (getState('0_userdata.0.go-e.DebugAktiv').val) {
      require('fs').appendFileSync('/opt/iobroker/log/' + datum + ' - Cupra.log', formatDate(new Date(), "hh:mm:ss") + " \t" + txt + "\n");}
}


// ------->>>> Phasenerkennung
// 57 = 1P, 63 = 3P Auto laden, 56 = kein Auto
schedule("* * * * * *", async () => {
  setState('0_userdata.0.go-e-phases.L1_Zuleitung' /* L1_Zuleitung */, (Math.floor(getState('go-e.0.phases').val / 8) % 2 === 1));
  setState('0_userdata.0.go-e-phases.L2_Zuleitung' /* L2_Zuleitung */, (Math.floor(getState('go-e.0.phases').val / 16) % 2 === 1));
  setState('0_userdata.0.go-e-phases.L3_Zuleitung' /* L3_Zuleitung */, (Math.floor(getState('go-e.0.phases').val / 32) % 2 === 1));
  setState('0_userdata.0.go-e-phases.L1_Auto' /* L1_Auto */, (Math.floor(getState('go-e.0.phases').val / 1) % 2 === 1));
  setState('0_userdata.0.go-e-phases.L2_Auto' /* L2_Auto */, (Math.floor(getState('go-e.0.phases').val / 2) % 2 === 1));
  setState('0_userdata.0.go-e-phases.L3_Auto' /* L3_Auto */, (Math.floor(getState('go-e.0.phases').val / 4) % 2 === 1));
  // ---->>> Phasendefinition
  if (getState('0_userdata.0.go-e-phases.L1_Auto').val == true && getState('0_userdata.0.go-e-phases.L2_Auto').val == true && getState('0_userdata.0.go-e-phases.L3_Auto').val == true && !getState('0_userdata.0.go-e.3P').val) {
    setState('0_userdata.0.go-e.1P' /* 1P */, false);
    setState('0_userdata.0.go-e.3P' /* 3P */, true);
    if (getState('0_userdata.0.go-e.minPV').val < 4500) {
      setState('0_userdata.0.go-e.minPV' /* minPVÜberschuss */, 4500);
    }
    await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), '-------->>> V3 3P Ladung erkannt');
  } else if (getState('0_userdata.0.go-e-phases.L1_Auto').val == true && getState('0_userdata.0.go-e-phases.L2_Auto').val == false && getState('0_userdata.0.go-e-phases.L3_Auto').val == false && !getState('0_userdata.0.go-e.1P').val) {
    setState('0_userdata.0.go-e.1P' /* 1P */, true);
    setState('0_userdata.0.go-e.3P' /* 3P */, false);
    if (getState('0_userdata.0.go-e.minPV').val > 1500) {
      setState('0_userdata.0.go-e.minPV' /* minPVÜberschuss */, 1500);
    }
    await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), '-------->>> V3 1P Ladung erkannt');
  }
  if (getState('0_userdata.0.go-e.1P').val == true) {
    setState('0_userdata.0.go-e.minW' /* minWatt */, (getState('0_userdata.0.go-e.minA').val * 230));
    await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), '-------->>> V3 minWatt lt. minAmpere');
  } else if (getState('0_userdata.0.go-e.3P').val == true) {
    setState('0_userdata.0.go-e.minW' /* minWatt */, (getState('0_userdata.0.go-e.minA').val * 3 * 230));
    await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), '-------->>> V3 minWatt lt. Berechnung');
  }
});
on({ id: '0_userdata.0.go-e-phases.Phasenumschaltung' /* Phasenumschaltung */, val: true }, async (obj) => {
  let value = obj.state.val;
  let oldValue = obj.oldState.val;
  if (getState('go-e.0.unlocked_by').val == 0) {
    if (getState('0_userdata.0.go-e.3P').val) {
      httpGet('http://192.168.11.20/api/set?psm=1', { timeout: 2000, responseType: 'text' }, async (err, response) => {
      });
      console.info('manuelle Umschaltung auf 1 Phase');
      await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), '-------->>> V3 manuelle 1 Phasenumschaltung');
    } else {
      httpGet('http://192.168.11.20/api/set?psm=2', { timeout: 2000, responseType: 'text' }, async (err, response) => {
      });
      console.info('manuelle Umschaltung auf 3 Phase');
      await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), '-------->>> V3 manuelle 3 Phasenumschaltung');
    }
    setStateDelayed('0_userdata.0.go-e-phases.Phasenumschaltung' /* Phasenumschaltung */, false, 2000, false);
  }
});
// automatische Phasenumschaltung
schedule("*/2 * * * *", async () => {
  if (getState('go-e.0.unlocked_by').val == 0) {
    // Umschaltung auf 1P
    if (getState('go-e.0.car').val >= 1 && getState('alias.0.Fronius.AC-Power').val <= 5000 && getState('go-e.0.energy.power').val == 0 && getState('0_userdata.0.go-e.3P').val && getState('0_userdata.0.go-e.AUTO').val && true) {
      httpGet('http://192.168.11.20/api/set?psm=1', { timeout: 2000, responseType: 'text' }, async (err, response) => {
      });
      setState('0_userdata.0.go-e.1P' /* 1P */, true);
      setState('0_userdata.0.go-e.3P' /* 3P */, false);
      setState('go-e.0.amperePV' /* Ampere for PWM (amx) (FW > 033 required) */, getState('0_userdata.0.go-e.minA').val);
      if (getState('0_userdata.0.go-e.minPV').val != 1500) {
        setState('0_userdata.0.go-e.minPV' /* minPVÜberschuss */, 1500);
      }
      await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), '-------->>> V3 automatische 1 Phasenumschaltung');
    }
    // Umschaltung auf 3P
    if (getState('go-e.0.allow_charging').val && getState('go-e.0.amperePV').val == getState('0_userdata.0.go-e.maxA').val && getState('alias.0.EM24 Hall Grid.PV_Überschuss').val >= 3000 && getState('alias.0.Fronius.AC-Power').val >= 8000 && getState('0_userdata.0.go-e.1P').val && getState('0_userdata.0.go-e.AUTO').val && true) {
      httpGet('http://192.168.11.20/api/set?psm=2', { timeout: 2000, responseType: 'text' }, async (err, response) => {
      });
      setState('0_userdata.0.go-e.1P' /* 1P */, false);
      setState('0_userdata.0.go-e.3P' /* 3P */, true);
      setState('go-e.0.amperePV' /* Ampere for PWM (amx) (FW > 033 required) */, getState('0_userdata.0.go-e.minA').val);
      if (getState('0_userdata.0.go-e.minPV').val != 4500) {
        setState('0_userdata.0.go-e.minPV' /* minPVÜberschuss */, 4500);
      }
      await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), '-------->>> V3 automatische 3 Phasenumschaltung');
    }
  }
});


